  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault();if(savingEvidence)return;const form=event.currentTarget,data = new FormData(form);setSavingEvidence(true);setError('');let saved=false;try { const created=await api<MarketEvidence>('/market-evidence', json({ title: data.get('title'), sourceType: data.get('sourceType'), sourceUrl: data.get('sourceUrl'), summary: data.get('summary'), rawContent: data.get('rawContent') }));saved=true;const projectId=String(data.get('projectId')||'');if(projectId)await api(`/product-projects/${projectId}/evidence`,json({evidenceId:created.id,note:'人工记录市场资料并纳入项目'}));form.reset();setOpen(false);setNotice(projectId?'市场记录已保存并关联项目，内容仍需自行核实。':'已保存到共享市场记录库，尚未关联项目。');await load(); } catch (e) {if(saved){setOpen(false);await load();}setError(`${saved?'记录已保存，但项目关联失败；请从项目关联已有记录，勿重复保存。 ':''}${e instanceof Error ? e.message : '保存失败'}`); }finally{setSavingEvidence(false);} }
